WITH flattened AS (SELECT id, host, log_ts, level, k, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS k, v) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, DATE_TRUNC('HOUR', log_ts) AS hour_window, COUNT(DISTINCT k) AS distinct_ks, COUNT_IF(k = 'version') AS version_events, SIZE(COLLECT_SET(k)) AS num_ks, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS span_minutes, COUNT(DISTINCT k) AS distinct_ks_2 FROM flattened GROUP BY 1, 2;
